export interface ValidationResult { isValid: boolean; errors: string[]; warnings: string[] }

export interface AmountPeriodValidationResult { isAmountValid: boolean; isPeriodValid: boolean; validationErrors: string[]; canProceed: boolean }

export interface ApprovalHierarchyResult { approvalLevel: string; approvers: string[]; estimatedDays: number; requiresPaperApproval: boolean }

export interface ApprovalAuthorityResult { hasAuthority: boolean; requiredPosition: string; nextApprover: string | null; processingRoute: string }

export interface ApprovalDecisionResult { decision: string; reason: string; conditionalRequirements: string[]; nextAction: string }

export interface NextApproverResult { nextApprover: string | null; processingRoute: string; isSubsidyRelated: boolean; requiresPaperStorage: boolean }

export interface ApproverAuthorityLevelResult { requiredAuthorityLevel: string; approverRoles: string[]; escalationRequired: boolean }

export function validateApplicationInput(
  documentTitle: string,
  documentContent: string,
  applicationType: string,
  applicantDepartment: string,
  urgencyLevel: string
): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Helper functions for validation
  const isValidApplicationTypeInternal = (type: string): boolean => {
    const validTypes = ['補助金申請', '設備申請', '人事申請', '予算申請', '研究申請'];
    return validTypes.includes(type);
  };

  const isValidDepartmentInternal = (department: string): boolean => {
    const validDepartments = ['研究推進部', '総務部', '経理部', '人事部', '企画部'];
    return validDepartments.includes(department);
  };

  const isValidUrgencyLevelInternal = (level: string): boolean => {
    const validLevels = ['通常', '急ぎ', '至急'];
    return validLevels.includes(level);
  };

  if (!documentTitle || documentTitle.length < 10 || documentTitle.length > 200) {
    errors.push("申請書類のタイトルは10文字以上200文字以内で入力してください");
  }

  if (!documentContent || documentContent.length < 50) {
    errors.push("申請内容は50文字以上で詳しく記載してください");
  }

  if (!applicationType || !isValidApplicationTypeInternal(applicationType)) {
    errors.push("申請種別を正しく選択してください");
  }

  if (!applicantDepartment || !isValidDepartmentInternal(applicantDepartment)) {
    errors.push("所属部署を正しく入力してください");
  }

  if (!urgencyLevel || !isValidUrgencyLevelInternal(urgencyLevel)) {
    errors.push("緊急度を選択してください");
  }

  const isValid = errors.length === 0;

  return { isValid, errors, warnings };
}

export function validateApplicationAmountAndPeriod(
  applicationAmount: number,
  implementationStartDate: string,
  implementationEndDate: string,
  documentType: string,
  budgetLimits: Record<string, {minAmount: number, maxAmount: number}>
): AmountPeriodValidationResult {
  const budgetLimit = budgetLimits[documentType];
  
  // 申請金額が予算上限の150%を超過している場合は例外をスロー
  if (applicationAmount > budgetLimit.maxAmount * 1.5) {
    throw new Error("申請金額が大幅に予算上限を超過しています。金額を見直してください");
  }
  
  const isAmountValid = applicationAmount >= budgetLimit.minAmount && applicationAmount <= budgetLimit.maxAmount;
  
  const startDate = new Date(implementationStartDate);
  const endDate = new Date(implementationEndDate);
  const today = new Date();
  const isPeriodValid = startDate >= today && endDate > startDate;
  
  const validationErrors: string[] = [];
  if (!isAmountValid) {
    validationErrors.push("申請金額が規定範囲外です");
  }
  if (!isPeriodValid) {
    validationErrors.push("実施期間が不正です");
  }
  
  const canProceed = isAmountValid && isPeriodValid;
  
  return {
    isAmountValid,
    isPeriodValid,
    validationErrors,
    canProceed
  };
}

export function determineApprovalHierarchy(applicationAmount: number, applicationType: string, applicantDepartment: string): ApprovalHierarchyResult {
  // バリデーション
  if (applicationAmount <= 0) {
    throw new Error("申請金額は1円以上で入力してください");
  }
  
  if (!applicantDepartment || applicantDepartment.trim() === "") {
    throw new Error("承認ルート設定のため、所属部署を入力してください");
  }

  let approvalLevel = "";
  let estimatedDays = 0;
  let requiresPaperApproval = false;
  
  // 補助金関連の判定
  if (applicationType.includes("補助金")) {
    if (applicationAmount >= 1000000) {
      approvalLevel = "理事承認";
      estimatedDays = 7;
    } else {
      approvalLevel = "部長承認";
      estimatedDays = 5;
    }
    requiresPaperApproval = true;
  } else {
    // 一般申請の場合
    if (applicationAmount < 100000) {
      approvalLevel = "課長承認";
      estimatedDays = 3;
    } else if (applicationAmount < 1000000) {
      approvalLevel = "部長承認";
      estimatedDays = 5;
    } else {
      approvalLevel = "理事承認";
      estimatedDays = 7;
    }
    requiresPaperApproval = false;
  }

  // 承認者リストの決定
  let approvers: string[] = [];
  if (approvalLevel === "課長承認") {
    approvers = ["課長"];
  } else if (approvalLevel === "部長承認") {
    approvers = ["部長"];
  } else if (approvalLevel === "理事承認") {
    approvers = ["理事"];
  }

  return {
    approvalLevel,
    approvers,
    estimatedDays,
    requiresPaperApproval
  };
}

export function determineApprovalAuthority(
  approverPosition: string,
  applicationAmount: number,
  applicationType: string,
  approvalAction: string
): ApprovalAuthorityResult {
  // バリデーション
  if (!approverPosition || approverPosition.trim() === "") {
    throw new Error("承認者の職位情報を確認できません。システム管理者にお問い合わせください。");
  }
  
  if (applicationAmount < 0) {
    throw new Error("申請金額に正しい値を入力してください。");
  }
  
  if (!applicationType || applicationType.trim() === "") {
    throw new Error("申請種別を選択してください。");
  }

  // 職位の権限レベルを定義
  const positionLevels: { [key: string]: number } = {
    "課長": 1,
    "部長": 2,
    "理事": 3
  };

  // 申請種別と金額から必要な職位を判定
  let requiredPosition: string;
  let requiredLevel: number;

  if (applicationType === "補助金申請") {
    if (applicationAmount <= 1000000) {
      requiredPosition = "課長";
      requiredLevel = 1;
    } else if (applicationAmount <= 5000000) {
      requiredPosition = "部長";
      requiredLevel = 2;
    } else {
      requiredPosition = "理事";
      requiredLevel = 3;
    }
  } else {
    // 一般申請など
    if (applicationAmount <= 3000000) {
      requiredPosition = "部長";
      requiredLevel = 2;
    } else {
      requiredPosition = "理事";
      requiredLevel = 3;
    }
  }

  // 承認者の権限レベルを取得
  const approverLevel = positionLevels[approverPosition];
  if (approverLevel === undefined) {
    throw new Error("承認者の職位情報を確認できません。システム管理者にお問い合わせください。");
  }

  // 権限判定
  const hasAuthority = approverLevel >= requiredLevel;

  if (!hasAuthority) {
    // 権限不足の場合、上位承認者にエスカレーション
    return {
      hasAuthority: false,
      requiredPosition,
      nextApprover: requiredPosition,
      processingRoute: "escalate"
    };
  }

  // 権限が十分な場合、承認判断に従って処理
  let processingRoute: string;
  switch (approvalAction) {
    case "approve":
      processingRoute = "approved";
      break;
    case "reject":
      processingRoute = "rejected";
      break;
    default:
      processingRoute = "returned";
      break;
  }

  return {
    hasAuthority: true,
    requiredPosition,
    nextApprover: null,
    processingRoute
  };
}

export function determineApprovalDecision(
  documentContent: string, 
  deficiencyItems: string[], 
  subsidyRelated: boolean, 
  urgencyLevel: number, 
  documentType?: string, 
  applicationType?: string
): ApprovalDecisionResult {
  if (!documentContent || documentContent.trim() === "") {
    throw new Error("申請書類の内容が入力されていません。承認判定を行うことができません。");
  }

  const clampedUrgencyLevel = Math.max(1, Math.min(5, urgencyLevel));
  
  const calculateDeficiencySeverityInternal = (items: string[]): number => {
    let score = 0;
    for (const item of items) {
      if (item.includes("金額") || item.includes("期間") || item.includes("添付")) {
        score += 3;
      } else {
        score += 1;
      }
    }
    return score;
  };

  const generateConditionalRequirementsInternal = (items: string[]): string[] => {
    return items.map(item => `${item}の修正が必要`);
  };

  const severityScore = calculateDeficiencySeverityInternal(deficiencyItems);
  const deficiencyCount = deficiencyItems.length;

  if (subsidyRelated && severityScore >= 7) {
    return { 
      decision: "reject", 
      reason: "補助金関連書類で重要な不備があるため", 
      conditionalRequirements: [], 
      nextAction: "resubmit" 
    };
  }

  if (deficiencyCount >= 3 || severityScore >= 8) {
    return { 
      decision: "reject", 
      reason: "重大な不備が複数あるため", 
      conditionalRequirements: [], 
      nextAction: "resubmit" 
    };
  }

  if (deficiencyCount >= 1 && clampedUrgencyLevel >= 4) {
    const requirements = generateConditionalRequirementsInternal(deficiencyItems);
    return { 
      decision: "conditional", 
      reason: "軽微な不備があるが緊急性を考慮", 
      conditionalRequirements: requirements, 
      nextAction: "fulfill_conditions" 
    };
  }

  return { 
    decision: "approve", 
    reason: "不備なしまたは軽微な不備のみ", 
    conditionalRequirements: [], 
    nextAction: "proceed" 
  };
}

export function determineNextApprover(
  documentTitle: string,
  documentContent: string,
  currentApproverRole: string,
  approvalDecision: string
): NextApproverResult {
  // バリデーション
  if (!documentTitle || documentTitle.trim() === "") {
    throw new Error("申請書類のタイトルが入力されていません。タイトルを入力してください。");
  }
  
  if (!currentApproverRole || currentApproverRole.trim() === "") {
    throw new Error("承認者の役職情報が取得できません。システム管理者にお問い合わせください。");
  }
  
  if (!approvalDecision || approvalDecision.trim() === "") {
    throw new Error("承認・差戻し・却下のいずれかを選択してください。");
  }

  // 補助金関連キーワードの分析
  const subsidyKeywords = [
    "補助金", "科研費", "科学研究費", "文部科学省", "運営費交付金", 
    "設備整備費", "研究費", "助成事業", "研究設備", "研究基盤"
  ];
  
  const titleContent = documentTitle + " " + documentContent;
  const totalWords = titleContent.split(/\s+/).length;
  const matchedKeywords = subsidyKeywords.filter(keyword => 
    titleContent.includes(keyword)
  ).length;
  
  const keywordScore = totalWords > 0 ? matchedKeywords / subsidyKeywords.length : 0;
  const isSubsidyRelated = keywordScore >= 0.7 || 
    titleContent.includes("科研費") || 
    titleContent.includes("補助金") || 
    titleContent.includes("文部科学省") ||
    titleContent.includes("運営費交付金") ||
    titleContent.includes("設備整備費");

  // 文科省要件チェック（紙保管が必要かどうか）
  const requiresPaperStorage = isSubsidyRelated && (
    titleContent.includes("文部科学省") ||
    titleContent.includes("科研費") ||
    titleContent.includes("科学研究費") ||
    titleContent.includes("運営費交付金") ||
    titleContent.includes("設備整備費")
  );

  // 処理ルート決定
  const processingRoute = requiresPaperStorage ? "hybrid" : "electronic";

  // 次の承認者決定
  let nextApprover: string | null = null;
  
  // 差し戻しや却下の場合は次の承認者はnull
  if (approvalDecision === "差し戻し" || approvalDecision === "差戻し" || 
      approvalDecision === "reject" || approvalDecision === "却下") {
    nextApprover = null;
  } else if (approvalDecision === "承認" || approvalDecision === "approve") {
    // 承認の場合、現在の役職に基づいて次の承認者を決定
    if (currentApproverRole === "課長" || currentApproverRole === "section_chief") {
      nextApprover = currentApproverRole === "section_chief" ? "department_head" : "部長";
    } else if (currentApproverRole === "部長" || currentApproverRole === "department_head") {
      nextApprover = "理事";
    } else if (currentApproverRole === "理事") {
      nextApprover = null; // 最終承認者
    }
  }

  return {
    nextApprover,
    processingRoute,
    isSubsidyRelated,
    requiresPaperStorage
  };
}

export function setApproverAuthorityLevel(
  documentType: string,
  subsidyRelated: boolean,
  paperStorageRequired: boolean,
  applicantDepartment: string,
  budgetAmount: number
): ApproverAuthorityLevelResult {
  if (applicantDepartment === "") {
    throw new Error("申請者の所属部署を選択してください");
  }
  
  if (budgetAmount < 0) {
    throw new Error("予算金額は0以上の値を入力してください");
  }

  const isHighBudget = budgetAmount > 5000000;
  const isVeryHighBudget = budgetAmount > 10000000;
  const needsHighAuthority = subsidyRelated || isHighBudget;
  const requiredAuthorityLevel = needsHighAuthority ? "department_head" : "section_chief";
  const approverRoles = [requiredAuthorityLevel];
  
  if (paperStorageRequired) {
    approverRoles.push("administrative_director");
  }
  
  const escalationRequired = isVeryHighBudget;
  
  return { requiredAuthorityLevel, approverRoles, escalationRequired };
}
